export type RIconName = keyof typeof DEFS;

const paint = (v?: "c" | "k") => (v === "c" ? "currentColor" : v === "k" ? "var(--layer-canvas)" : "none");

export function RIcon({ name, filled = false, ...props }: { name: RIconName; filled?: boolean } & SVGProps<SVGSVGElement>) {
  const def: Def = DEFS[name];
  const parts = filled && def.f ? def.f : def.o;
  return (
    <svg viewBox="0 0 20 20" width="20" height="20" fill="none" strokeLinecap="butt" strokeLinejoin="miter" aria-hidden="true" data-ricon={name} {...props}>
      {parts.map((p, i) => (
        <path key={i} d={p.d} stroke={paint(p.s)} fill={paint(p.f)} fillRule={p.e ? "evenodd" : undefined} strokeWidth={p.s ? (p.w ?? 1) : undefined} vectorEffect="non-scaling-stroke" />
      ))}
    </svg>
  );
}
